package com.servicerca.model;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="application") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class ServiceApplication { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="request_id") private ServiceRequest request; @ManyToOne(optional=false) @JoinColumn(name="professional_id") private User professional; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) @Builder.Default private ApplicationStatus status=ApplicationStatus.PENDING; @Column(length=500) private String message; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void prePersist(){if(createdAt==null)createdAt=Instant.now();} }
